const quotePremium = (step: QuoteStep): number => {
  const policyBasePremium = step.items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  return policyBasePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE;
};

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step) => ({ premium: quotePremium(step) })),
});
